 "content": "from collections import Counter


def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    # The model is the longest contiguous horizontal run of non-background cells.
    runs = []
    for r, row in enumerate(grid):
        c = 0
        while c < w:
            if row[c] == background:
                c += 1
                continue
            start = c
            while c < w and row[c] != background:
                c += 1
            runs.append((c - start, r, start, row[start:c]))
    _, _, _, motif = max(runs, key=lambda item: item[0])
    anchor = len(motif) // 2
    motif_colors = set(motif)

    # Isolated marks in the remaining color indicate where to stamp the motif;
    # its middle cell is aligned with each mark.
    marks = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row)
             if value != background and value not in motif_colors]
    for r, c in marks:
        start = c - anchor
        for i, value in enumerate(motif):
            x = start + i
            if 0 <= x < w:
                out[r][x] = value
    return out
